import React, { useState, useEffect, useMemo } from 'react';
import Navbar from './components/Navbar';
import AIChat from './components/AIChat';
import AdminDashboard from './components/AdminDashboard';
import MenuView from './components/MenuView';
import CartView from './components/CartView';
import AccountView from './components/AccountView';
import TraiteurView from './components/TraiteurView';
import ItemDetailsModal from './components/ItemDetailsModal';
import Receipt from './components/Receipt';
import Toast, { ToastType } from './components/Toast';
import ReviewsSection from './components/ReviewsSection';
import DeliveryEstimator from './components/DeliveryEstimator';
import { KhadyLogo } from './components/KhadyLogo';
import { playSound } from './utils/audio';
import { Page, MenuItem, CartItem, Order } from './types';
import { MENU_ITEMS, REVIEWS } from './constants';
import { Heart, Megaphone, Plus } from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [splashFade, setSplashFade] = useState(false);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [toast, setToast] = useState<{message: string, type: ToastType} | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [showReceipt, setShowReceipt] = useState<Order | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setSplashFade(true);
      setTimeout(() => setShowSplash(false), 800);
    }, 3000);
    return () => clearTimeout(timer);
  }, []);

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const existing = cart.find(i => i.id === item.id && i.instructions === instructions);
    if (existing) {
      setCart(cart.map(i => i === existing ? { ...i, quantity: i.quantity + quantity } : i));
    } else {
      setCart([...cart, { ...item, quantity, instructions }]);
    }
    setToast({ message: `${item.name} ajouté au panier !`, type: 'success' });
    playSound('pop');
  };

  const handleOrderPlace = (order: Order) => {
    setOrders([order, ...orders]);
    setCurrentPage(Page.HOME);
    setShowReceipt(order);
    setToast({ message: "Commande reçue ! Barka !", type: 'success' });
  };

  const favoris = useMemo(() => items.filter(i => i.rating === 5).slice(0, 1), [items]);

  if (showSplash) {
    return (
      <div className={`fixed inset-0 z-[100] bg-brand-brown flex flex-col items-center justify-center transition-opacity duration-1000 ${splashFade ? 'opacity-0' : 'opacity-100'}`}>
        <div className="flex flex-col items-center animate-pulse">
           <KhadyLogo variant="light" className="scale-150 mb-8" />
           <p className="text-brand-gold font-black tracking-[0.5em] uppercase text-[10px] italic">L'excellence de Niamey</p>
        </div>
      </div>
    );
  }

  if (isAdmin) {
    return (
      <AdminDashboard 
        items={items} 
        setItems={setItems} 
        orders={orders} 
        setOrders={setOrders} 
        reviews={REVIEWS} 
        setReviews={() => {}} 
        onExit={() => setIsAdmin(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-brand-light flex flex-col items-center overflow-x-hidden selection:bg-brand-orange selection:text-white">
      {toast && <Toast {...toast} onClose={() => setToast(null)} />}
      {showReceipt && <Receipt order={showReceipt} onClose={() => setShowReceipt(null)} />}

      <main className="flex-1 w-full max-w-lg bg-brand-light min-h-screen pb-32">
        {currentPage === Page.HOME && (
          <div className="animate-fade-in relative">
            <div className="bg-[#FAF3E0] p-8 rounded-b-[3.5rem] shadow-sm mb-6 border-b border-brand-brown/5">
              <header className="flex justify-between items-start mb-10 h-16">
                <KhadyLogo variant="dark" />
              </header>
              <div className="mb-4">
                 <h2 className="text-4xl font-black italic uppercase leading-none text-brand-brown">
                   Barka ! <br/>
                   <span className="text-brand-orange">Cher Gourmet</span>
                 </h2>
              </div>
            </div>

            <div className="bg-brand-brown py-3 mb-8 overflow-hidden">
               <div className="flex animate-marquee whitespace-nowrap gap-12 items-center">
                  {[...Array(4)].map((_, i) => (
                    <div key={i} className="flex items-center gap-4 text-brand-gold font-black uppercase italic text-[9px] tracking-[0.2em]">
                       <Megaphone size={14} className="text-brand-orange" />
                       <span>Livraison Express avec Billo</span>
                    </div>
                  ))}
               </div>
            </div>

            <div className="px-6">
              <div className="mb-12">
                 <h3 className="text-xl font-black italic uppercase text-brand-brown mb-6 flex items-center gap-2">
                   <Heart className="text-brand-orange fill-brand-orange" size={20} /> Le Choix du Chef
                 </h3>
                 <div className="w-full h-72 bg-white rounded-[3.5rem] overflow-hidden shadow-2xl border-4 border-white relative cursor-pointer group" onClick={() => setSelectedItem(favoris[0])}>
                    <img src={favoris[0]?.image} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" alt="Favori" />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent"></div>
                    <div className="absolute bottom-10 left-10 right-10">
                       <h4 className="text-3xl font-black text-white uppercase italic leading-none mb-4">{favoris[0]?.name}</h4>
                       <div className="flex justify-between items-center">
                          <span className="text-brand-orange font-black text-2xl">{favoris[0]?.price} F</span>
                          <div className="bg-brand-orange p-3 rounded-2xl text-white shadow-xl transition-transform active:scale-90"><Plus size={24} /></div>
                       </div>
                    </div>
                 </div>
              </div>

              <ReviewsSection reviews={REVIEWS} />
              <div className="mt-16"><DeliveryEstimator /></div>
            </div>
          </div>
        )}

        {currentPage === Page.MENU && (
          <MenuView items={items} onSelectItem={setSelectedItem} />
        )}

        {currentPage === Page.CART && (
          <CartView cart={cart} setCart={setCart} onOrderPlace={handleOrderPlace} onClose={() => setCurrentPage(Page.HOME)} />
        )}

        {currentPage === Page.TRAITEUR && <TraiteurView />}

        {currentPage === Page.COMPTE && (
          <AccountView orders={orders} onAdminAccess={() => setIsAdmin(true)} />
        )}
      </main>

      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.reduce((a, b) => a + b.quantity, 0)} />
      <AIChat />
      <ItemDetailsModal 
        item={selectedItem} 
        isOpen={!!selectedItem} 
        onClose={() => setSelectedItem(null)} 
        onAddToCart={handleAddToCart} 
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { MenuItem, MenuCategory } from '../types';
import { Search, SlidersHorizontal, Flame, Leaf, Star, Plus } from 'lucide-react';
import { playSound } from '../utils/audio';

interface MenuViewProps {
  items: MenuItem[];
  onSelectItem: (item: MenuItem) => void;
}

const CATEGORIES: MenuCategory[] = [
  'Plat Africain', 'Box Sauce', 'Spécialité Maison', 'Plat Européen', 'Entrée Chaude', 'Dessert', 'Boisson Froide'
];

const MenuView: React.FC<MenuViewProps> = ({ items, onSelectItem }) => {
  const [selectedCategory, setSelectedCategory] = useState<MenuCategory | 'TOUT'>('TOUT');
  const [searchQuery, setSearchQuery] = useState('');

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const matchesCategory = selectedCategory === 'TOUT' || item.category === selectedCategory;
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [items, selectedCategory, searchQuery]);

  return (
    <div className="animate-fade-in pt-6">
      <header className="px-6 mb-8">
        <h2 className="text-3xl font-black italic uppercase text-brand-brown leading-tight mb-6">
          Notre Carte <br/>
          <span className="text-brand-orange text-lg tracking-[0.3em]">Gastronomique</span>
        </h2>

        <div className="flex gap-3 mb-8">
           <div className="flex-1 bg-white rounded-2xl shadow-sm border border-gray-100 flex items-center px-4 gap-3">
              <Search size={18} className="text-gray-300" />
              <input 
                type="text" 
                placeholder="Rechercher un délice..." 
                className="w-full py-4 text-xs font-bold outline-none bg-transparent"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
           </div>
           <button className="bg-brand-brown text-brand-gold p-4 rounded-2xl shadow-lg transition-transform active:scale-90">
              <SlidersHorizontal size={20} />
           </button>
        </div>

        <div className="flex gap-4 overflow-x-auto no-scrollbar -mx-6 px-6 pb-2">
           <button 
             onClick={() => setSelectedCategory('TOUT')}
             className={`px-6 py-3 rounded-full text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${selectedCategory === 'TOUT' ? 'bg-brand-orange text-white shadow-lg' : 'bg-white text-gray-400 border border-gray-100'}`}
           >
             Tout
           </button>
           {CATEGORIES.map(cat => (
             <button 
               key={cat}
               onClick={() => setSelectedCategory(cat)}
               className={`px-6 py-3 rounded-full text-[10px] font-black uppercase tracking-widest whitespace-nowrap transition-all ${selectedCategory === cat ? 'bg-brand-orange text-white shadow-lg' : 'bg-white text-gray-400 border border-gray-100'}`}
             >
               {cat}
             </button>
           ))}
        </div>
      </header>

      <div className="px-6 grid grid-cols-2 gap-5">
         {filteredItems.map(item => (
           <div 
             key={item.id} 
             onClick={() => { playSound('pop'); onSelectItem(item); }}
             className="bg-white rounded-[2.5rem] p-4 shadow-sm border border-brand-brown/5 relative group cursor-pointer active:scale-95 transition-all"
           >
              <div className="relative h-32 w-full mb-4 overflow-hidden rounded-[1.8rem]">
                 <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={item.name} />
                 {item.isSpicy && (
                   <div className="absolute top-2 right-2 bg-red-500 text-white p-1.5 rounded-full shadow-lg border-2 border-white">
                      <Flame size={12} fill="white" />
                   </div>
                 )}
                 {item.rating === 5 && (
                   <div className="absolute bottom-2 left-2 bg-brand-gold text-brand-brown px-2 py-1 rounded-lg text-[8px] font-black flex items-center gap-1 border border-white">
                      <Star size={8} fill="currentColor" /> BEST
                   </div>
                 )}
              </div>

              <h4 className="text-[11px] font-black text-brand-brown uppercase italic leading-tight mb-2 line-clamp-2">{item.name}</h4>

              <div className="flex justify-between items-center mt-auto">
                 <span className="text-xs font-black text-brand-orange">{item.price} F</span>
                 <div className="w-8 h-8 bg-brand-brown text-brand-gold rounded-xl flex items-center justify-center shadow-lg transition-transform active:scale-90">
                    <Plus size={16} />
                 </div>
              </div>
           </div>
         ))}
      </div>

      {filteredItems.length === 0 && (
        <div className="py-20 text-center opacity-20 italic">
           Aucun plat trouvé dans cette catégorie.
        </div>
      )}
    </div>
  );
};

export default MenuView;

import React, { useState } from 'react';
import { CartItem, Order, PaymentMethod } from '../types';
import { Trash2, ShoppingBag, ArrowRight, MapPin, Smartphone, ChevronLeft, ShieldCheck } from 'lucide-react';
import { PhoneInput } from './PhoneInput';
import { playSound } from '../utils/audio';
import { BILLO_INFO, DISTRICTS } from '../constants';

interface CartViewProps {
  cart: CartItem[];
  setCart: React.Dispatch<React.SetStateAction<CartItem[]>>;
  onOrderPlace: (order: Order) => void;
  onClose: () => void;
}

const CartView: React.FC<CartViewProps> = ({ cart, setCart, onOrderPlace, onClose }) => {
  const [customer, setCustomer] = useState({ name: '', phone: '', address: '', district: 'Plateau' });
  const [payment, setPayment] = useState<PaymentMethod>('CASH');

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const getDeliveryFee = () => {
    const district = DISTRICTS.find(d => d.name === customer.district);
    const hour = new Date().getHours();
    const isNight = hour >= 21 || hour < 6;

    if (!district) return 0;

    if (district.zone === 'center') {
      return isNight ? BILLO_INFO.tarifs.center.night : BILLO_INFO.tarifs.center.day;
    } else {
      return isNight ? BILLO_INFO.tarifs.periphery.night : BILLO_INFO.tarifs.periphery.day;
    }
  };

  const deliveryFee = cart.length > 0 ? getDeliveryFee() : 0;
  const total = subtotal + deliveryFee;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customer.name || !customer.phone) return alert("Complétez vos coordonnées");

    const newOrder: Order = {
      id: `KH-${Math.floor(1000 + Math.random() * 9000)}`,
      customerName: customer.name,
      phone: customer.phone,
      address: customer.address,
      district: customer.district,
      items: [...cart],
      total: subtotal,
      deliveryFee: deliveryFee,
      status: 'RECEIVED',
      paymentMethod: payment,
      timestamp: new Date().toISOString()
    };

    onOrderPlace(newOrder);
    setCart([]);
    playSound('cash');
  };

  return (
    <div className="animate-fade-in p-6">
      <header className="mb-10 flex items-center gap-4">
        <button onClick={onClose} className="w-12 h-12 bg-white rounded-2xl shadow-sm border border-gray-100 flex items-center justify-center text-brand-brown">
           <ChevronLeft size={24} />
        </button>
        <h2 className="text-3xl font-black italic uppercase text-brand-brown leading-none">Mon <span className="text-brand-orange">Panier</span></h2>
      </header>

      {cart.length === 0 ? (
        <div className="py-20 flex flex-col items-center justify-center opacity-20 grayscale">
           <ShoppingBag size={80} className="mb-6 text-brand-brown" />
           <p className="font-black uppercase text-[10px] tracking-widest text-brand-brown mb-8 italic">Votre panier est vide</p>
           <button onClick={onClose} className="text-brand-orange font-black uppercase text-[10px] underline tracking-widest">Retour au menu</button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="space-y-4">
             {cart.map((item, idx) => (
               <div key={idx} className="bg-white p-5 rounded-[2.5rem] flex items-center gap-5 shadow-sm border border-brand-brown/5 group transition-all hover:shadow-lg">
                  <div className="relative w-16 h-16 rounded-2xl overflow-hidden shadow-md">
                     <img src={item.image} className="w-full h-full object-cover" alt={item.name} />
                  </div>
                  <div className="flex-1">
                     <h4 className="font-black text-[10px] text-brand-brown uppercase italic truncate mb-1">{item.name}</h4>
                     <p className="text-[10px] font-black text-brand-orange bg-brand-orange/5 px-2 py-1 rounded-lg inline-block">{item.quantity} x {item.price} F</p>
                  </div>
                  <button type="button" onClick={() => { playSound('pop'); setCart(cart.filter((_, i) => i !== idx)); }} className="p-3 text-red-400 transition-transform active:scale-90"><Trash2 size={20}/></button>
               </div>
             ))}
          </div>

          <div className="bg-[#1A0F0D] p-10 rounded-[3.5rem] shadow-2xl border-4 border-white text-white relative overflow-hidden">
             <div className="absolute top-0 right-0 p-8 opacity-5 rotate-12"><MapPin size={100} /></div>
             <h3 className="text-brand-gold font-black uppercase italic text-xs tracking-widest mb-8 flex items-center gap-2 relative z-10"><MapPin size={16}/> Livraison Billo Express</h3>
             <div className="space-y-4 relative z-10">
                <input type="text" required placeholder="Votre Nom" className="w-full p-5 bg-white/5 rounded-2xl text-white text-xs font-bold outline-none border border-white/10 focus:border-brand-gold" value={customer.name} onChange={e => setCustomer({...customer, name: e.target.value})} />
                <PhoneInput value={customer.phone} onChange={(v) => setCustomer({...customer, phone: v})} required />
                <div className="relative">
                  <select className="w-full p-5 bg-white/10 rounded-2xl text-white text-xs font-bold outline-none border border-white/10 appearance-none cursor-pointer" value={customer.district} onChange={e => setCustomer({...customer, district: e.target.value})}>
                     <optgroup label="Centre-Ville (1000f)" className="bg-brand-brown">
                        {DISTRICTS.filter(d => d.zone === 'center').map(d => <option key={d.name} value={d.name}>{d.name}</option>)}
                     </optgroup>
                     <optgroup label="Périphérie (1500f)" className="bg-brand-brown">
                        {DISTRICTS.filter(d => d.zone === 'periphery').map(d => <option key={d.name} value={d.name}>{d.name}</option>)}
                     </optgroup>
                  </select>
                </div>
                <input type="text" placeholder="Précisions adresse (Villa n°, Rue...)" className="w-full p-5 bg-white/5 rounded-2xl text-white text-xs font-bold outline-none border border-white/10 focus:border-brand-gold" value={customer.address} onChange={e => setCustomer({...customer, address: e.target.value})} />
             </div>
          </div>

          <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-gray-50">
             <h3 className="text-brand-brown font-black uppercase italic text-xs tracking-widest mb-8 flex items-center gap-3"><Smartphone size={16} className="text-brand-orange"/> Mode de Paiement</h3>
             <div className="grid grid-cols-2 gap-3">
                {[
                  { id: 'CASH', l: 'Espèces 💵' }, { id: 'AIRTEL_MONEY', l: 'Airtel' }, { id: 'MOOV_MONEY', l: 'Moov' },
                  { id: 'MYNITA', l: 'MyNita' }, { id: 'AMANATA', l: 'Amanata' }, { id: 'ALLIZA', l: 'Alliza' }
                ].map(m => (
                  <button key={m.id} type="button" onClick={() => { playSound('pop'); setPayment(m.id as any); }} className={`p-4 rounded-2xl text-[9px] font-black uppercase border-4 transition-all shadow-sm ${payment === m.id ? 'border-brand-orange bg-brand-orange text-white shadow-brand-orange/20' : 'border-gray-50 bg-gray-50 text-brand-brown/40'}`}>{m.l}</button>
                ))}
             </div>
          </div>

          <div className="bg-brand-brown p-10 rounded-[4rem] text-brand-gold shadow-2xl relative overflow-hidden border-4 border-white">
             <div className="space-y-4 mb-8">
                <div className="flex justify-between text-white/40 text-[9px] font-black uppercase tracking-widest"><span>Sous-total Festin</span><span>{subtotal} F</span></div>
                <div className="flex justify-between text-brand-gold text-[9px] font-black uppercase tracking-widest"><span>Service Billo (Zone {DISTRICTS.find(d => d.name === customer.district)?.zone})</span><span>{deliveryFee} F</span></div>
                <div className="pt-6 border-t border-white/10 flex justify-between items-end"><span className="text-white font-black italic uppercase text-sm">Net à Payer</span><span className="text-4xl font-black">{total} F</span></div>
             </div>
             <button type="submit" className="w-full bg-brand-orange text-white py-6 rounded-[2.5rem] font-black uppercase shadow-[0_20px_50px_rgba(255,111,0,0.3)] flex items-center justify-center gap-4 active:scale-95 transition-all italic tracking-widest">Confirmer le Festin <ArrowRight size={22}/></button>
             <p className="text-center text-[8px] text-white/20 font-black uppercase tracking-widest mt-6">Sécurisé par Khady's Payment Terminal</p>
          </div>
        </form>
      )}
    </div>
  );
};

export default CartView;

import React, { useState, useEffect, useMemo } from 'react';
import Navbar from './components/Navbar';
import AIChat from './components/AIChat';
import AdminDashboard from './components/AdminDashboard';
import MenuView from './components/MenuView';
import CartView from './components/CartView';
import AccountView from './components/AccountView';
import TraiteurView from './components/TraiteurView';
import ItemDetailsModal from './components/ItemDetailsModal';
import Receipt from './components/Receipt';
import Toast, { ToastType } from './components/Toast';
import ReviewsSection from './components/ReviewsSection';
import DeliveryEstimator from './components/DeliveryEstimator';
import { KhadyLogo } from './components/KhadyLogo';
import { playSound } from './utils/audio';
import { Page, MenuItem, CartItem, Order } from './types';
import { MENU_ITEMS, REVIEWS } from './constants';
import { Heart, Megaphone, Plus, Sparkles } from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [splashFade, setSplashFade] = useState(false);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [toast, setToast] = useState<{message: string, type: ToastType} | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [showReceipt, setShowReceipt] = useState<Order | null>(null);
  const [isAdmin, setIsAdmin] = useState(false);

  // Splash Screen Logic
  useEffect(() => {
    const timer = setTimeout(() => {
      setSplashFade(true);
      setTimeout(() => setShowSplash(false), 800);
    }, 2500);
    return () => clearTimeout(timer);
  }, []);

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const existing = cart.find(i => i.id === item.id && i.instructions === instructions);
    if (existing) {
      setCart(cart.map(i => i === existing ? { ...i, quantity: i.quantity + quantity } : i));
    } else {
      setCart([...cart, { ...item, quantity, instructions }]);
    }
    setToast({ message: `${item.name} ajouté au panier !`, type: 'success' });
    playSound('pop');
  };

  const handleOrderPlace = (order: Order) => {
    setOrders([order, ...orders]);
    setCurrentPage(Page.HOME);
    setShowReceipt(order);
    setToast({ message: "Commande reçue ! Barka !", type: 'success' });
    playSound('cash');
  };

  const favori = useMemo(() => items.find(i => i.id === 'sp1') || items[0], [items]);

  if (showSplash) {
    return (
      <div className={`fixed inset-0 z-[100] bg-brand-brown flex flex-col items-center justify-center transition-opacity duration-1000 ${splashFade ? 'opacity-0' : 'opacity-100'}`}>
        <div className="flex flex-col items-center animate-pulse">
           <KhadyLogo variant="light" className="scale-150 mb-8" />
           <div className="flex items-center gap-2 mt-4">
              <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-bounce"></div>
              <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-bounce [animation-delay:0.2s]"></div>
              <div className="w-1.5 h-1.5 bg-brand-gold rounded-full animate-bounce [animation-delay:0.4s]"></div>
           </div>
        </div>
      </div>
    );
  }

  if (isAdmin) {
    return (
      <AdminDashboard 
        items={items} 
        setItems={setItems} 
        orders={orders} 
        setOrders={setOrders} 
        reviews={REVIEWS} 
        setReviews={() => {}} 
        onExit={() => setIsAdmin(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-brand-light flex flex-col items-center overflow-x-hidden selection:bg-brand-orange selection:text-white">
      {toast && <Toast {...toast} onClose={() => setToast(null)} />}
      {showReceipt && <Receipt order={showReceipt} onClose={() => setShowReceipt(null)} />}

      <main className="flex-1 w-full max-w-lg bg-brand-light min-h-screen pb-32">
