interface MenuViewProps {
  items: MenuItem[];
  onSelectItem: (item: MenuItem) => void;
}

const CATEGORIES: (MenuCategory | 'TOUT')[] = [
  'TOUT', 'Plat Africain', 'Box Sauce', 'Spécialité Maison', 'Plat Européen', 'Entrée Chaude', 'Dessert', 'Boisson Froide'
];

