                <KhadyLogo variant="dark" />
                {/* RESTAURATION DE LA MAIN 👋🏾 ET DES MESSAGES DYNAMIQUES */}
                <div className="flex items-center gap-3 bg-white px-4 py-2 rounded-2xl shadow-md border border-brand-brown/5 animate-fade-in">
                   <div className="flex flex-col items-end">
                      <span className="text-[10px] font-black uppercase text-brand-orange animate-pulse">
                        {WELCOME_MESSAGES[welcomeIdx]} !
                      </span>
                      <span className="text-[8px] font-bold text-brand-brown/40 uppercase">Gourmet</span>
                   </div>
                   <span className="text-2xl animate-wave origin-bottom-right inline-block">👋🏾</span>
