              </div>
            </div>

            <div className="bg-brand-brown py-3 mb-8 overflow-hidden">
               <div className="flex animate-marquee whitespace-nowrap gap-12 items-center text-brand-gold font-black uppercase italic text-[9px] tracking-[0.2em]">
