import React, { useState, useEffect } from 'react';
import { DISTRICTS, BILLO_LOGO_URL, DELIVERY_TIME, BILLO_INFO } from '../constants';
import { Clock, MapPin, AlertCircle } from 'lucide-react';

const DeliveryEstimator: React.FC = () => {
  const [selectedDistrict, setSelectedDistrict] = useState<string>('');
  const [time, setTime] = useState<string>('');
  const [price, setPrice] = useState<number | null>(null);

  useEffect(() => {
    const now = new Date();
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    setTime(`${hours}:${minutes}`);
  }, []);

  const calculate = () => {
    if (!selectedDistrict || !time) return;
    const district = DISTRICTS.find(d => d.name === selectedDistrict);
    if (!district) return;

    const hour = parseInt(time.split(':')[0]);
    const isNight = hour >= 21 || hour < 6;

    let calculatedPrice = 0;
    if (district.zone === 'center') {
      calculatedPrice = isNight ? BILLO_INFO.tarifs.center.night : BILLO_INFO.tarifs.center.day;
    } else {
      calculatedPrice = isNight ? BILLO_INFO.tarifs.periphery.night : BILLO_INFO.tarifs.periphery.day;
    }
    setPrice(calculatedPrice);
  };

  useEffect(() => {
    calculate();
  }, [selectedDistrict, time]);

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl p-8 mb-6 border border-gray-100 relative overflow-hidden">
      <div className="flex items-center space-x-5 mb-8">
        <div className="w-14 h-14 rounded-2xl border-2 border-brand-orange bg-white p-1.5 shadow-md flex items-center justify-center overflow-hidden">
            <img src={BILLO_LOGO_URL} alt="Billo Express" className="w-full h-full object-contain" />
        </div>
        <div>
          <h3 className="font-black text-brand-brown uppercase tracking-tighter text-lg italic">{BILLO_INFO.name}</h3>
          <p className="text-[10px] text-brand-orange font-black uppercase tracking-[0.2em]">Livraison éclair à Niamey</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-8">
        <div className="space-y-2">
          <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 ml-2">
            <MapPin size={10} className="text-brand-orange" /> Zone
          </label>
          <select value={selectedDistrict} onChange={(e) => setSelectedDistrict(e.target.value)} className="w-full text-xs p-5 bg-[#F8F9FA] rounded-[1.8rem] border-none focus:ring-1 focus:ring-brand-orange font-bold appearance-none cursor-pointer">
            <option value="">Quartier...</option>
            {DISTRICTS.map(d => (<option key={d.name} value={d.name}>{d.name}</option>))}
          </select>
        </div>
        <div className="space-y-2">
          <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-2 ml-2">
