import React, { useState, useEffect, useMemo } from 'react';
import Navbar from './components/Navbar';
import AIChat from './components/AIChat';
import AdminDashboard from './components/AdminDashboard';
import MenuView from './components/MenuView';
import CartView from './components/CartView';
import AccountView from './components/AccountView';
import TraiteurView from './components/TraiteurView';
import ItemDetailsModal from './components/ItemDetailsModal';
import UpsellModal from './components/UpsellModal';
import Receipt from './components/Receipt';
import Toast, { ToastType } from './components/Toast';
import { Page, MenuItem, Order, Review, CartItem } from './types';
import { MENU_ITEMS, REVIEWS } from './constants';
import { playSound } from './utils/audio';

// Fix: Complete the main App component with state management and routing logic
const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [reviews, setReviews] = useState<Review[]>(REVIEWS);
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [isItemModalOpen, setIsItemModalOpen] = useState(false);
  const [isUpsellOpen, setIsUpsellOpen] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);
  const [toast, setToast] = useState<{ message: string, type: ToastType } | null>(null);

  const showToast = (message: string, type: ToastType = 'success') => {
    setToast({ message, type });
  };

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const cartItem: CartItem = { ...item, quantity, instructions };
    setCart(prev => [...prev, cartItem]);
    showToast(`${quantity}x ${item.name} ajouté !`);
    playSound('pop');

    // Si c'est un plat principal, on propose un accompagnement (upsell)
    if (item.category === 'Plat Africain' || item.category === 'Plat Européen' || item.category === 'Spécialité Maison') {
      setIsUpsellOpen(true);
    }
  };

  const handleOrderPlace = (order: Order) => {
    setOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCurrentPage(Page.HOME);
    showToast("Commande reçue ! Nos chefs s'activent. 👨‍🍳");
  };

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME:
        return (
          <div className="pb-32 px-6 pt-10 animate-fade-in">
            <header className="mb-10">
              <h1 className="text-4xl font-black italic text-brand-brown uppercase tracking-tighter leading-none mb-2">
                Khady's <br/>
                <span className="text-brand-orange">Food & Event</span>
              </h1>
              <p className="text-[10px] font-black uppercase text-gray-400 tracking-[0.3em]">L'excellence au service de vos papilles</p>
            </header>

            <div className="relative mb-10 group cursor-pointer" onClick={() => setCurrentPage(Page.MENU)}>
               <div className="absolute inset-0 bg-gradient-to-t from-brand-brown/80 to-transparent z-10 rounded-[3rem]"></div>
               <img src="https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=800" className="w-full h-80 object-cover rounded-[3rem] shadow-2xl transition-transform duration-700 group-hover:scale-105" alt="Banner" />
               <div className="absolute bottom-8 left-8 z-20">
                  <span className="bg-brand-orange text-white text-[8px] font-black px-4 py-1.5 rounded-full uppercase italic mb-3 inline-block shadow-lg">Suggestion du Chef</span>
                  <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter leading-none">Découvrir <br/> Notre Carte</h2>
               </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
               <button onClick={() => setCurrentPage(Page.MENU)} className="bg-white p-8 rounded-[2.5rem] shadow-xl border border-gray-50 flex flex-col items-center text-center transition-all active:scale-95 group">
                  <div className="w-14 h-14 bg-brand-orange/10 rounded-2xl flex items-center justify-center text-brand-orange mb-4 group-hover:bg-brand-orange group-hover:text-white transition-colors"><ShoppingBag size={24}/></div>
                  <span className="text-[10px] font-black uppercase text-brand-brown tracking-widest italic">Nos Box</span>
               </button>
               <button onClick={() => setCurrentPage(Page.TRAITEUR)} className="bg-brand-brown p-8 rounded-[2.5rem] shadow-xl flex flex-col items-center text-center transition-all active:scale-95 group border-4 border-white">
                  <div className="w-14 h-14 bg-brand-gold/10 rounded-2xl flex items-center justify-center text-brand-gold mb-4 group-hover:bg-brand-gold group-hover:text-brand-brown transition-colors">✨</div>
                  <span className="text-[10px] font-black uppercase text-brand-gold tracking-widest italic">Évent</span>
               </button>
            </div>
          </div>
        );
      case Page.MENU:
        return <MenuView items={items} onSelectItem={(item) => { setSelectedItem(item); setIsItemModalOpen(true); }} />;
      case Page.TRAITEUR:
        return <TraiteurView />;
      case Page.CART:
        return <CartView cart={cart} setCart={setCart} onOrderPlace={handleOrderPlace} onClose={() => setCurrentPage(Page.MENU)} />;
      case Page.COMPTE:
        return <AccountView orders={orders} onAdminAccess={() => setCurrentPage(Page.ADMIN)} />;
      case Page.ADMIN:
        return <AdminDashboard items={items} setItems={setItems} orders={orders} setOrders={setOrders} reviews={reviews} setReviews={setReviews} onExit={() => setCurrentPage(Page.COMPTE)} />;
      default:
        return <MenuView items={items} onSelectItem={(item) => { setSelectedItem(item); setIsItemModalOpen(true); }} />;
    }
  };

  const upsellSuggestions = useMemo(() => {
    return items.filter(i => i.category === 'Boisson Froide' || i.category === 'Dessert').slice(0, 3);
  }, [items]);

  return (
    <div className="min-h-screen bg-[#FDFCFB] font-sans text-brand-brown selection:bg-brand-orange selection:text-white">
      {renderPage()}

      {currentPage !== Page.ADMIN && (
        <>
          <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.reduce((a, b) => a + b.quantity, 0)} />
          <AIChat />
        </>
      )}

      <ItemDetailsModal 
        item={selectedItem} 
        isOpen={isItemModalOpen} 
        onClose={() => setIsItemModalOpen(false)} 
        onAddToCart={handleAddToCart} 
      />

      <UpsellModal 
        isOpen={isUpsellOpen} 
        onClose={() => setIsUpsellOpen(false)} 
        suggestions={upsellSuggestions}
        onAdd={(item) => { handleAddToCart(item, 1, ''); setIsUpsellOpen(false); }}
        onProceed={() => { setIsUpsellOpen(false); setCurrentPage(Page.CART); }}
      />

      {lastOrder && (
        <Receipt order={lastOrder} onClose={() => setLastOrder(null)} />
      )}

      {toast && (
        <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />
      )}
    </div>
  );
};

export default App;

