                  className="absolute inset-0 w-full h-full object-cover animate-zoom-dezoom" 
                  alt="Banner" 
                />
                <div className="absolute inset-0 z-20 flex flex-col justify-center px-10">
                  <span className="bg-brand-orange text-white text-[7px] font-black px-4 py-1 rounded-full uppercase italic mb-3 self-start shadow-lg">Premium Niamey</span>
                  <h2 className="text-3xl font-black text-white italic uppercase tracking-tighter leading-none shadow-text">Le Goût de <br/> l'Afrique</h2>
                </div>
              </div>
            </div>

            {/* Action Grid Conforme Image */}
            <div className="px-6 grid grid-cols-5 gap-3 mb-10">
              <div className="col-span-3 bg-[#2D1B18] rounded-[2.5rem] p-6 shadow-xl flex flex-col items-center justify-center relative overflow-hidden group active:scale-95 transition-all cursor-pointer" onClick={() => setCurrentPage(Page.MENU)}>
                <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
                <div className="w-14 h-14 bg-brand-gold/10 rounded-2xl flex items-center justify-center text-brand-gold mb-3 relative z-10"><Utensils size={28}/></div>
                <span className="text-[10px] font-black uppercase text-brand-gold tracking-[0.3em] italic relative z-10">La Carte</span>
              </div>
              <div className="col-span-2 space-y-2">
                <button onClick={() => setCurrentPage(Page.MENU)} className="w-full bg-brand-gold text-brand-brown py-4 rounded-2xl font-black uppercase text-[8px] italic flex items-center justify-center gap-2 shadow-lg shadow-brand-gold/20 active:scale-95 transition-all">
                  <ShoppingBag size={14}/> Pack-Buffet
                </button>
                <button onClick={() => setCurrentPage(Page.MENU)} className="w-full bg-brand-orange text-white py-4 rounded-2xl font-black uppercase text-[8px] italic flex items-center justify-center gap-2 shadow-lg shadow-brand-orange/20 active:scale-95 transition-all">
                  <ShoppingBag size={14}/> Box Sauce
                </button>
                <button onClick={() => setCurrentPage(Page.TRAITEUR)} className="w-full bg-white text-brand-brown py-4 rounded-2xl font-black uppercase text-[8px] italic border border-gray-100 flex items-center justify-center gap-2 shadow-sm active:scale-95 transition-all">
                  <ShoppingBag size={14}/> Event/Devis
                </button>
              </div>
            </div>

            {/* Les Incontournables avec Défilement Infini */}
            <section className="mb-10 overflow-hidden">
              <div className="flex items-center gap-2 mb-6 px-6">
                <Heart size={16} fill="#FF6F00" className="text-brand-orange" />
                <h3 className="text-[11px] font-black uppercase text-brand-brown tracking-[0.2em] italic">Les Incontournables</h3>
              </div>
              <div className="relative">
                <div className="flex animate-infinite-scroll w-[200%] gap-4 px-6">
                  {/* Premier lot */}
                  {[...items.slice(0, 5)].map((item) => (
                    <div key={item.id} className="w-48 flex-shrink-0 bg-white rounded-[2.5rem] p-4 shadow-xl border border-gray-50 flex flex-col cursor-pointer active:scale-95 transition-all" onClick={() => { setSelectedItem(item); setIsItemModalOpen(true); playSound('pop'); }}>
                      <img src={item.image} className="w-full h-32 object-cover rounded-[1.8rem] mb-4 shadow-md" alt={item.name} />
                      <h4 className="text-[9px] font-black uppercase text-brand-brown italic mb-2 truncate">{item.name}</h4>
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black text-brand-orange">{item.price} F</span>
                        <div className="flex gap-0.5">
                          {[...Array(4)].map((_, i) => <Star key={i} size={8} fill="#FFD700" className="text-brand-gold" />)}
                        </div>
                      </div>
                    </div>
                  ))}
                  {/* Deuxième lot pour la boucle infinie */}
                  {[...items.slice(0, 5)].map((item) => (
                    <div key={`${item.id}-dup`} className="w-48 flex-shrink-0 bg-white rounded-[2.5rem] p-4 shadow-xl border border-gray-50 flex flex-col cursor-pointer" onClick={() => { setSelectedItem(item); setIsItemModalOpen(true); playSound('pop'); }}>
                      <img src={item.image} className="w-full h-32 object-cover rounded-[1.8rem] mb-4 shadow-md" alt={item.name} />
                      <h4 className="text-[9px] font-black uppercase text-brand-brown italic mb-2 truncate">{item.name}</h4>
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black text-brand-orange">{item.price} F</span>
                        <div className="flex gap-0.5">
                          {[...Array(4)].map((_, i) => <Star key={i} size={8} fill="#FFD700" className="text-brand-gold" />)}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </section>

            {/* Billo Express Section */}
            <div className="px-6 mb-10">
              <DeliveryEstimator />
            </div>

            {/* Avis de nos Gourmets */}
            <div className="px-6">
              <ReviewsSection reviews={reviews} />
            </div>
          </div>
        );
      case Page.MENU:
        return <MenuView items={items} onSelectItem={(item) => { setSelectedItem(item); setIsItemModalOpen(true); }} />;
      case Page.TRAITEUR:
        return <TraiteurView />;
      case Page.CART:
        return <CartView cart={cart} setCart={setCart} onOrderPlace={handleOrderPlace} onClose={() => setCurrentPage(Page.MENU)} />;
      case Page.COMPTE:
        return <AccountView orders={orders} onAdminAccess={() => setCurrentPage(Page.ADMIN)} />;
      case Page.ADMIN:
        return <AdminDashboard items={items} setItems={setItems} orders={orders} setOrders={setOrders} reviews={reviews} setReviews={setReviews} onExit={() => setCurrentPage(Page.COMPTE)} />;
      default:
        return <MenuView items={items} onSelectItem={(item) => { setSelectedItem(item); setIsItemModalOpen(true); }} />;
    }
  };

  const upsellSuggestions = useMemo(() => {
    return items.filter(i => i.category === 'Boisson Froide' || i.category === 'Dessert').slice(0, 3);
  }, [items]);

  return (
    <div className="min-h-screen bg-[#FDFCFB] font-sans text-brand-brown selection:bg-brand-orange selection:text-white">
      {renderPage()}

      {currentPage !== Page.ADMIN && (
        <>
          <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.reduce((a, b) => a + b.quantity, 0)} />
          <AIChat />
        </>
      )}

      <ItemDetailsModal 
        item={selectedItem} 
        isOpen={isItemModalOpen} 
        onClose={() => setIsItemModalOpen(false)} 
        onAddToCart={handleAddToCart} 
      />

      <UpsellModal 
        isOpen={isUpsellOpen} 
        onClose={() => setIsUpsellOpen(false)} 
        suggestions={upsellSuggestions}
        onAdd={(item) => { handleAddToCart(item, 1, ''); setIsUpsellOpen(false); }}
        onProceed={() => { setIsUpsellOpen(false); setCurrentPage(Page.CART); }}
      />

      {lastOrder && (
        <Receipt order={lastOrder} onClose={() => setLastOrder(null)} />
      )}

      {toast && (
        <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />
      )}
    </div>
  );
};

