import React, { useState } from 'react';
import { Order } from '../types';
import { 
  ShoppingBag, Gift, ChevronRight, LogOut, Settings, 
  Award, QrCode, Phone, User, Mail, Lock, 
  ArrowRight, Sparkles, Fingerprint
} from 'lucide-react';
import { playSound } from '../utils/audio';
import { PasswordInput } from './PasswordInput';
import { PhoneInput } from './PhoneInput';

interface AccountViewProps {
  orders: Order[];
  onAdminAccess: () => void;
}

const AccountView: React.FC<AccountViewProps> = ({ orders, onAdminAccess }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<'login' | 'register'>('login');
  const [adminTapCount, setAdminTapCount] = useState(0);

  // Geste secret pour l'admin : 7 clics rapides sur l'avatar
  const handleSecretAdmin = () => {
    const newCount = adminTapCount + 1;
    if (newCount >= 7) {
      playSound('success');
      onAdminAccess();
      setAdminTapCount(0);
    } else {
      setAdminTapCount(newCount);
      setTimeout(() => setAdminTapCount(0), 3000);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="animate-fade-in p-6 pb-32 min-h-[85vh] flex flex-col justify-center">
        <div className="bg-white rounded-[3.5rem] p-10 shadow-2xl border border-gray-100 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-10 opacity-5 rotate-12">
            <Fingerprint size={120} className="text-brand-brown" />
          </div>

          {/* TABS CONNEXION / INSCRIPTION */}
          <div className="flex gap-4 mb-10 p-1.5 bg-gray-50 rounded-2xl relative z-10">
            <button 
              onClick={() => setActiveTab('login')}
              className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'login' ? 'bg-brand-brown text-brand-gold shadow-lg' : 'text-gray-300'}`}
            >
              Se Connecter
            </button>
            <button 
              onClick={() => setActiveTab('register')}
              className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'register' ? 'bg-brand-brown text-brand-gold shadow-lg' : 'text-gray-300'}`}
            >
              S'inscrire
            </button>
          </div>

          <div className="text-center mb-8 relative z-10">
            <h2 className="text-2xl font-black italic uppercase text-brand-brown tracking-tighter">
              {activeTab === 'register' ? "Rejoindre le Club" : "Bon retour !"}
            </h2>
            <p className="text-[9px] font-black uppercase text-brand-orange tracking-[0.3em] mt-2">
              L'élite culinaire de Niamey
            </p>
          </div>

          <form className="space-y-4 relative z-10" onSubmit={(e) => { e.preventDefault(); setIsLoggedIn(true); playSound('success'); }}>
            {activeTab === 'register' && (
              <div className="relative">
                <User className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
                <input type="text" placeholder="Nom complet" required className="w-full p-5 pl-14 bg-gray-50 rounded-2xl text-brand-brown text-xs font-bold outline-none border-2 border-transparent focus:border-brand-orange/20 transition-all" />
              </div>
            )}

            <PhoneInput value="" onChange={() => {}} required className="!bg-gray-50 text-brand-brown border-2 border-transparent focus-within:border-brand-orange/20" />

            <div className="relative">
              <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
              <input type="email" placeholder={`Email ${activeTab === 'register' ? '(Optionnel)' : ''}`} className="w-full p-5 pl-14 bg-gray-50 rounded-2xl text-brand-brown text-xs font-bold outline-none border-2 border-transparent focus:border-brand-orange/20 transition-all" />
            </div>

            <PasswordInput name="pass" placeholder="Mot de passe" required />

            <button type="submit" className="w-full bg-brand-brown text-brand-gold py-6 rounded-3xl font-black uppercase italic shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all mt-4">
              {activeTab === 'register' ? "Créer mon accès" : "Ouvrir ma session"} <ArrowRight size={20} />
            </button>
          </form>

          {activeTab === 'login' && (
            <p className="mt-6 text-center text-[9px] font-bold text-gray-300 uppercase tracking-widest cursor-pointer hover:text-brand-orange">
              Mot de passe oublié ?
            </p>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-in p-6 pb-32">
      {/* HEADER PROFIL - COPIE CONFORME CAPTURE */}
      <header className="flex flex-col items-center mb-10 pt-10">
         <div 
           className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl p-1 mb-4 border-4 border-brand-orange/10 relative cursor-pointer active:scale-95 transition-transform"
           onClick={handleSecretAdmin}
         >
            <img src="https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200" className="w-full h-full object-cover rounded-[2.2rem]" alt="Profile" />
            <div className="absolute -bottom-2 -right-2 bg-brand-orange text-white w-8 h-8 rounded-full flex items-center justify-center border-4 border-brand-light shadow-lg">
               <Award size={16} />
            </div>
         </div>
         <h2 className="text-2xl font-black italic uppercase text-brand-brown mb-1">Abdou R.</h2>
         <p className="text-[10px] font-black text-brand-orange uppercase tracking-[0.2em] italic">Membre Club Gold ✨</p>
      </header>

      {/* STATS FIDÉLITÉ - COPIE CONFORME CAPTURE */}
      <div className="grid grid-cols-2 gap-4 mb-8">
         <div className="bg-[#2D1B18] p-6 rounded-[2.5rem] text-brand-gold shadow-xl border-4 border-white flex flex-col items-center text-center">
            <span className="text-[8px] font-black uppercase tracking-widest text-white/40 mb-2">Points Fidélité</span>
            <span className="text-2xl font-black italic mb-2">1,250</span>
            <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden mb-2">
               <div className="bg-brand-gold h-full w-[65%] shadow-[0_0_10px_#FFD700]"></div>
            </div>
            <span className="text-[7px] font-bold text-white/40 uppercase tracking-widest">En route vers Platinum</span>
         </div>
         <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col items-center text-center">
            <span className="text-[8px] font-black uppercase tracking-widest text-gray-300 mb-2">Commandes</span>
            <span className="text-2xl font-black italic text-brand-brown mb-2">{orders.length + 12}</span>
            <div className="flex gap-1.5 mt-2">
               {[...Array(5)].map((_, i) => <div key={i} className="w-2 h-2 bg-brand-orange rounded-full opacity-20"></div>)}
            </div>
         </div>
      </div>

      {/* RACCOURCIS - COPIE CONFORME CAPTURE */}
      <div className="space-y-4 mb-10">
         <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-[0.3em] ml-4 mb-4">Mes Raccourcis</h3>
         {[
           { icon: ShoppingBag, label: 'Historique des Commandes', color: 'text-brand-brown' },
           { icon: Gift, label: 'Mes Récompenses & Cadeaux', color: 'text-brand-orange' },
           { icon: QrCode, label: 'Mon Code Client Khady', color: 'text-brand-brown' },
           { icon: Settings, label: 'Paramètres du Profil', color: 'text-gray-300' },
         ].map((item, i) => (
           <button key={i} className="w-full bg-white p-6 rounded-[2.2rem] shadow-sm border border-gray-100 flex items-center justify-between group active:scale-95 transition-all">
              <div className="flex items-center gap-5">
                 <div className={`w-12 h-12 rounded-2xl bg-gray-50 flex items-center justify-center ${item.color} shadow-inner`}>
                    <item.icon size={20} />
                 </div>
                 <span className="text-[11px] font-black uppercase italic text-brand-brown tracking-tight">{item.label}</span>
              </div>
              <ChevronRight size={16} className="text-gray-200 group-hover:text-brand-orange transition-colors" />
           </button>
         ))}
      </div>

      <button 
        onClick={() => { setIsLoggedIn(false); playSound('pop'); }}
        className="w-full py-6 rounded-[2.5rem] border-4 border-dashed border-gray-100 text-gray-300 flex items-center justify-center gap-3 font-black uppercase text-[9px] italic tracking-[0.4em] active:scale-95 transition-all mb-10"
      >
         <LogOut size={16} /> Déconnexion
      </button>

      <p className="text-center text-[7px] font-black text-gray-200 uppercase tracking-[0.5em] mb-10">
        Khady's Food & Event v2.5 • Niamey
      </p>
    </div>
  );
};

export default AccountView;

