import DeliveryEstimator from './components/DeliveryEstimator';
import ReviewsSection from './components/ReviewsSection';
import { Page, MenuItem, Order, Review, CartItem } from './types';
import { MENU_ITEMS, REVIEWS, LOGO_URL } from './constants';
import { playSound } from './utils/audio';
import { ShoppingBag, TrendingUp, User, Heart, Utensils, Star } from 'lucide-react';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [reviews, setReviews] = useState<Review[]>(REVIEWS);
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [isItemModalOpen, setIsItemModalOpen] = useState(false);
  const [isUpsellOpen, setIsUpsellOpen] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);
  const [toast, setToast] = useState<{ message: string, type: ToastType } | null>(null);

  // Messages de bienvenue dynamiques
  const [greetingIndex, setGreetingIndex] = useState(0);
  const greetings = [
    "SALAM 👋🏾",
    "BONJOUR 👋🏾",
    "BARKA 👋🏾",
    "FOFO 👋🏾",
    "QU'EST-CE QUE VOUS VOULEZ MANGER ? 😋"
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setGreetingIndex((prev) => (prev + 1) % greetings.length);
    }, 3500);
    return () => clearInterval(interval);
  }, []);

  const showToast = (message: string, type: ToastType = 'success') => {
    setToast({ message, type });
  };

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const cartItem: CartItem = { ...item, quantity, instructions };
    setCart(prev => [...prev, cartItem]);
    showToast(`${quantity}x ${item.name} ajouté !`);
    playSound('pop');

    if (item.category === 'Plat Africain' || item.category === 'Plat Européen' || item.category === 'Spécialité Maison') {
      setIsUpsellOpen(true);
    }
  };

  const handleOrderPlace = (order: Order) => {
    setOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCurrentPage(Page.HOME);
    showToast("Commande reçue ! Nos chefs s'activent. 👨‍🍳");
  };

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME:
        return (
          <div className="pb-32 animate-fade-in">
            <header className="px-6 pt-6 flex justify-between items-center mb-6">
              <div className="flex items-center gap-3">
                <img src={LOGO_URL} alt="Logo" className="w-10 h-10 rounded-full border-2 border-brand-brown/10 shadow-sm" />
                <div className="flex flex-col">
                  <h1 className="text-[12px] font-black italic text-brand-brown uppercase tracking-tighter leading-none">Khady's</h1>
                  <span className="text-[8px] font-black text-brand-orange uppercase tracking-widest leading-none mt-1">Food & Event</span>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <div className="bg-gray-50 px-4 py-2 rounded-2xl border border-gray-100 flex items-center justify-center h-10 min-w-[120px]">
                  <span className="text-[8px] font-black text-brand-brown uppercase italic tracking-wider animate-fade-in text-center" key={greetingIndex}>
                    {greetings[greetingIndex]}
                  </span>
                </div>
                <button onClick={() => setCurrentPage(Page.COMPTE)} className="w-10 h-10 bg-gray-100 rounded-2xl flex items-center justify-center text-gray-300 active:scale-90 transition-transform"><User size={20}/></button>
              </div>
            </header>

            <div className="px-6 mb-8 overflow-hidden rounded-[3rem]">
              <div className="relative h-48 group cursor-pointer overflow-hidden rounded-[3rem] shadow-2xl" onClick={() => setCurrentPage(Page.MENU)}>
                <div className="absolute inset-0 z-10 bg-gradient-to-r from-black/60 via-black/20 to-transparent"></div>
                <img 
                  src="https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=800" 
                  className="absolute inset-0 w-full h-full object-cover animate-zoom-dezoom" 
                  alt="Banner" 
                />
                <div className="absolute inset-0 z-20 flex flex-col justify-center px-10">
                  <span className="bg-brand-orange text-white text-[7px] font-black px-4 py-1 rounded-full uppercase italic mb-3 self-start shadow-lg">Premium Niamey</span>
                  <h2 className="text-3xl font-black text-white italic uppercase tracking-tighter leading-none">Le Goût de <br/> l'Afrique</h2>
                </div>
              </div>
            </div>

            <div className="px-6 grid grid-cols-5 gap-3 mb-10">
              <div className="col-span-3 bg-[#2D1B18] rounded-[2.5rem] p-6 shadow-xl flex flex-col items-center justify-center relative overflow-hidden group active:scale-95 transition-all cursor-pointer" onClick={() => setCurrentPage(Page.MENU)}>
                <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-10"></div>
                <div className="w-14 h-14 bg-brand-gold/10 rounded-2xl flex items-center justify-center text-brand-gold mb-3 relative z-10"><Utensils size={28}/></div>
                <span className="text-[10px] font-black uppercase text-brand-gold tracking-[0.3em] italic relative z-10">La Carte</span>
              </div>
              <div className="col-span-2 space-y-2">
                <button onClick={() => setCurrentPage(Page.MENU)} className="w-full bg-brand-gold text-brand-brown py-4 rounded-2xl font-black uppercase text-[8px] italic flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all">
                   Pack-Buffet
                </button>
                <button onClick={() => setCurrentPage(Page.MENU)} className="w-full bg-brand-orange text-white py-4 rounded-2xl font-black uppercase text-[8px] italic flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all">
                   Box Sauce
                </button>
                <button onClick={() => setCurrentPage(Page.TRAITEUR)} className="w-full bg-white text-brand-brown py-4 rounded-2xl font-black uppercase text-[8px] italic border border-gray-100 flex items-center justify-center gap-2 shadow-sm active:scale-95 transition-all">
                   Event/Devis
                </button>
              </div>
            </div>

            <section className="mb-10 overflow-hidden">
              <div className="flex items-center gap-2 mb-6 px-6">
                <Heart size={16} fill="#FF6F00" className="text-brand-orange" />
                <h3 className="text-[11px] font-black uppercase text-brand-brown tracking-[0.2em] italic">Les Incontournables</h3>
              </div>
              <div className="relative">
                <div className="flex animate-infinite-scroll w-[200%] gap-4 px-6">
                  {[...items.slice(0, 5), ...items.slice(0, 5)].map((item, i) => (
                    <div key={i} className="w-48 flex-shrink-0 bg-white rounded-[2.5rem] p-4 shadow-xl border border-gray-50 flex flex-col cursor-pointer active:scale-95 transition-all" onClick={() => { setSelectedItem(item); setIsItemModalOpen(true); playSound('pop'); }}>
                      <img src={item.image} className="w-full h-32 object-cover rounded-[1.8rem] mb-4 shadow-md" alt={item.name} />
                      <h4 className="text-[9px] font-black uppercase text-brand-brown italic mb-2 truncate">{item.name}</h4>
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black text-brand-orange">{item.price} F</span>
                        <div className="flex gap-0.5">
                          {[...Array(4)].map((_, i) => <Star key={i} size={8} fill="#FFD700" className="text-brand-gold" />)}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </section>

            <div className="px-6 mb-10">
              <DeliveryEstimator />
            </div>

            <div className="px-6">
              <ReviewsSection reviews={reviews} />
            </div>
          </div>
        );
      case Page.MENU:
        return <MenuView items={items} onSelectItem={(item) => { setSelectedItem(item); setIsItemModalOpen(true); }} />;
      case Page.TRAITEUR:
        return <TraiteurView />;
      case Page.CART:
        return <CartView cart={cart} setCart={setCart} onOrderPlace={handleOrderPlace} onClose={() => setCurrentPage(Page.MENU)} />;
      case Page.COMPTE:
        return <AccountView orders={orders} onAdminAccess={() => setCurrentPage(Page.ADMIN)} />;
      case Page.ADMIN:
        return <AdminDashboard items={items} setItems={setItems} orders={orders} setOrders={setOrders} reviews={reviews} setReviews={setReviews} onExit={() => setCurrentPage(Page.COMPTE)} />;
      default:
        return <MenuView items={items} onSelectItem={(item) => { setSelectedItem(item); setIsItemModalOpen(true); }} />;
    }
  };

  const upsellSuggestions = useMemo(() => {
    return items.filter(i => i.category === 'Boisson Froide' || i.category === 'Dessert').slice(0, 3);
  }, [items]);

  return (
    <div className="min-h-screen bg-[#FDFCFB] font-sans text-brand-brown selection:bg-brand-orange selection:text-white">
      {renderPage()}

      {currentPage !== Page.ADMIN && (
        <>
          <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.reduce((a, b) => a + b.quantity, 0)} />
          <AIChat />
        </>
      )}

      <ItemDetailsModal 
        item={selectedItem} 
        isOpen={isItemModalOpen} 
        onClose={() => setIsItemModalOpen(false)} 
        onAddToCart={handleAddToCart} 
      />

      <UpsellModal 
        isOpen={isUpsellOpen} 
        onClose={() => setIsUpsellOpen(false)} 
        suggestions={upsellSuggestions}
        onAdd={(item) => { handleAddToCart(item, 1, ''); setIsUpsellOpen(false); }}
        onProceed={() => { setIsUpsellOpen(false); setCurrentPage(Page.CART); }}
      />

      {lastOrder && (
        <Receipt order={lastOrder} onClose={() => setLastOrder(null)} />
      )}

      {toast && (
        <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Home, ScrollText, ShoppingBag, Sparkles, UserRound } from 'lucide-react';
import { Page } from '../types';
import { playSound } from '../utils/audio';

interface NavbarProps {
  currentPage: Page;
  setPage: (page: Page) => void;
  cartCount: number;
}

const Navbar: React.FC<NavbarProps> = ({ currentPage, setPage, cartCount }) => {
  const [isBouncing, setIsBouncing] = useState(false);
  const prevCount = useRef(cartCount);

  useEffect(() => {
    if (cartCount > prevCount.current) {
      setIsBouncing(true);
      const timer = setTimeout(() => setIsBouncing(false), 500);
      return () => clearTimeout(timer);
    }
    prevCount.current = cartCount;
  }, [cartCount]);

  const navItems = [
    { page: Page.HOME, icon: Home, label: 'Accueil' },
    { page: Page.MENU, icon: ScrollText, label: 'Menu' },
    { page: Page.TRAITEUR, icon: Sparkles, label: 'Event' },
    { page: Page.CART, icon: ShoppingBag, label: 'Panier', badge: cartCount },
    { page: Page.COMPTE, icon: UserRound, label: 'Moi' },
  ];

  return (
    <div className="fixed bottom-8 left-0 right-0 z-50 px-6 flex justify-center">
      <nav className="bg-white/80 backdrop-blur-2xl border border-gray-100 shadow-[0_20px_50px_rgba(0,0,0,0.1)] flex justify-between items-center h-20 px-4 rounded-[2.5rem] w-full max-w-sm">
          {navItems.map((item) => {
            const isActive = currentPage === item.page;
            const isCart = item.page === Page.CART;
            const Icon = item.icon;

            return (
              <button 
                key={item.label} 
                onClick={() => { playSound('pop'); setPage(item.page); }} 
                className="relative flex flex-col items-center justify-center flex-1 h-full group"
              >
                <div className={`relative p-3 rounded-2xl transition-all duration-300 ${isActive ? 'bg-brand-brown text-brand-gold shadow-lg shadow-brand-brown/20 scale-110' : 'text-gray-300 group-hover:text-brand-brown'} ${isCart && isBouncing ? 'animate-bounce-subtle' : ''}`}>
                  <Icon size={20} strokeWidth={isActive ? 2 : 1.2} />

                  {item.badge ? (
                    <span className="absolute -top-1 -right-1 bg-brand-orange text-white text-[8px] font-black w-4 h-4 rounded-full flex items-center justify-center border-2 border-white shadow-md">
                      {item.badge}
                    </span>
                  ) : null}
                </div>
              </button>
            );
          })}
      </nav>
    </div>
  );
};

export default Navbar;

import React, { useState } from 'react';
import { Order } from '../types';
import { 
  ShoppingBag, Gift, ChevronRight, LogOut, Settings, 
  Award, QrCode, Phone, User, Mail, Lock, 
  ArrowRight, Sparkles, Fingerprint
} from 'lucide-react';
import { playSound } from '../utils/audio';
import { PasswordInput } from './PasswordInput';
import { PhoneInput } from './PhoneInput';

interface AccountViewProps {
  orders: Order[];
  onAdminAccess: () => void;
}

const AccountView: React.FC<AccountViewProps> = ({ orders, onAdminAccess }) => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState<'login' | 'register'>('login');
  const [adminTapCount, setAdminTapCount] = useState(0);

  // Geste secret pour l'admin : 7 clics rapides sur l'avatar
  const handleSecretAdmin = () => {
    const newCount = adminTapCount + 1;
    if (newCount >= 7) {
      playSound('success');
      onAdminAccess();
      setAdminTapCount(0);
    } else {
      setAdminTapCount(newCount);
      setTimeout(() => setAdminTapCount(0), 3000);
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="animate-fade-in p-6 pb-32 min-h-[85vh] flex flex-col justify-center">
        <div className="bg-white rounded-[3.5rem] p-10 shadow-2xl border border-gray-100 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-10 opacity-5 rotate-12">
            <Fingerprint size={120} className="text-brand-brown" />
          </div>

          <div className="flex gap-4 mb-10 p-1.5 bg-gray-50 rounded-2xl relative z-10">
            <button 
              onClick={() => setActiveTab('login')}
              className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'login' ? 'bg-brand-brown text-brand-gold shadow-lg' : 'text-gray-300'}`}
            >
              Se Connecter
            </button>
            <button 
              onClick={() => setActiveTab('register')}
              className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'register' ? 'bg-brand-brown text-brand-gold shadow-lg' : 'text-gray-300'}`}
            >
              S'inscrire
            </button>
          </div>

          <div className="text-center mb-8 relative z-10">
            <h2 className="text-2xl font-black italic uppercase text-brand-brown tracking-tighter">
              {activeTab === 'register' ? "Rejoindre le Club" : "Bon retour !"}
            </h2>
            <p className="text-[9px] font-black uppercase text-brand-orange tracking-[0.3em] mt-2">
              L'élite culinaire de Niamey
            </p>
          </div>

          <form className="space-y-4 relative z-10" onSubmit={(e) => { e.preventDefault(); setIsLoggedIn(true); playSound('success'); }}>
            {activeTab === 'register' && (
              <div className="relative">
                <User className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
                <input type="text" placeholder="Nom complet" required className="w-full p-5 pl-14 bg-gray-50 rounded-2xl text-brand-brown text-xs font-bold outline-none border-2 border-transparent focus:border-brand-orange/20 transition-all" />
              </div>
            )}

            <PhoneInput value="" onChange={() => {}} required className="!bg-gray-50 text-brand-brown border-2 border-transparent focus-within:border-brand-orange/20" />

            <div className="relative">
              <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-gray-300" size={18} />
              <input 
                type="email" 
                placeholder={`Email ${activeTab === 'register' || activeTab === 'login' ? '(Optionnel)' : ''}`} 
                className="w-full p-5 pl-14 bg-gray-50 rounded-2xl text-brand-brown text-xs font-bold outline-none border-2 border-transparent focus:border-brand-orange/20 transition-all" 
              />
            </div>

            <PasswordInput name="pass" placeholder="Mot de passe" required />

            <button type="submit" className="w-full bg-brand-brown text-brand-gold py-6 rounded-3xl font-black uppercase italic shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all mt-4">
              {activeTab === 'register' ? "Créer mon accès" : "Ouvrir ma session"} <ArrowRight size={20} />
            </button>
          </form>

          {activeTab === 'login' && (
            <p className="mt-6 text-center text-[9px] font-bold text-gray-300 uppercase tracking-widest cursor-pointer hover:text-brand-orange">
              Mot de passe oublié ?
            </p>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-in p-6 pb-32">
      <header className="flex flex-col items-center mb-10 pt-10">
         <div 
           className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl p-1 mb-4 border-4 border-brand-orange/10 relative cursor-pointer active:scale-95 transition-transform"
           onClick={handleSecretAdmin}
         >
            <img src="https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200" className="w-full h-full object-cover rounded-[2.2rem]" alt="Profile" />
            <div className="absolute -bottom-2 -right-2 bg-brand-orange text-white w-8 h-8 rounded-full flex items-center justify-center border-4 border-brand-light shadow-lg">
               <Award size={16} />
            </div>
         </div>
         <h2 className="text-2xl font-black italic uppercase text-brand-brown mb-1">Abdou R.</h2>
         <p className="text-[10px] font-black text-brand-orange uppercase tracking-[0.2em] italic">Membre Club Gold ✨</p>
      </header>

      <div className="grid grid-cols-2 gap-4 mb-8">
         <div className="bg-[#2D1B18] p-6 rounded-[2.5rem] text-brand-gold shadow-xl border-4 border-white flex flex-col items-center text-center">
            <span className="text-[8px] font-black uppercase tracking-widest text-white/40 mb-2">Points Fidélité</span>
            <span className="text-2xl font-black italic mb-2">1,250</span>
            <div className="w-full h-1.5 bg-white/10 rounded-full overflow-hidden mb-2">
               <div className="bg-brand-gold h-full w-[65%] shadow-[0_0_10px_#FFD700]"></div>
            </div>
            <span className="text-[7px] font-bold text-white/40 uppercase tracking-widest">En route vers Platinum</span>
         </div>
         <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border border-gray-100 flex flex-col items-center text-center">
            <span className="text-[8px] font-black uppercase tracking-widest text-gray-300 mb-2">Commandes</span>
            <span className="text-2xl font-black italic text-brand-brown mb-2">{orders.length + 12}</span>
            <div className="flex gap-1.5 mt-2">
               {[...Array(5)].map((_, i) => <div key={i} className="w-2 h-2 bg-brand-orange rounded-full opacity-20"></div>)}
            </div>
         </div>
      </div>

      <div className="space-y-4 mb-10">
         <h3 className="text-[10px] font-black uppercase text-gray-400 tracking-[0.3em] ml-4 mb-4">Mes Raccourcis</h3>
         {[
           { icon: ShoppingBag, label: 'Historique des Commandes', color: 'text-brand-brown' },
           { icon: Gift, label: 'Mes Récompenses & Cadeaux', color: 'text-brand-orange' },
           { icon: QrCode, label: 'Mon Code Client Khady', color: 'text-brand-brown' },
           { icon: Settings, label: 'Paramètres du Profil', color: 'text-gray-300' },
         ].map((item, i) => (
           <button key={i} className="w-full bg-white p-6 rounded-[2.2rem] shadow-sm border border-gray-100 flex items-center justify-between group active:scale-95 transition-all">
              <div className="flex items-center gap-5">
                 <div className={`w-12 h-12 rounded-2xl bg-gray-50 flex items-center justify-center ${item.color} shadow-inner`}>
                    <item.icon size={20} />
                 </div>
                 <span className="text-[11px] font-black uppercase italic text-brand-brown tracking-tight">{item.label}</span>
              </div>
              <ChevronRight size={16} className="text-gray-200 group-hover:text-brand-orange transition-colors" />
           </button>
         ))}
      </div>

      <button 
        onClick={() => { setIsLoggedIn(false); playSound('pop'); }}
        className="w-full py-6 rounded-[2.5rem] border-4 border-dashed border-gray-100 text-gray-300 flex items-center justify-center gap-3 font-black uppercase text-[9px] italic tracking-[0.4em] active:scale-95 transition-all mb-10"
      >
         <LogOut size={16} /> Déconnexion
      </button>

      <p className="text-center text-[7px] font-black text-gray-200 uppercase tracking-[0.5em] mb-10">
        Khady's Food & Event v2.5 • Niamey
      </p>
    </div>
  );
};

export default AccountView;

import React, { useState, useEffect, useMemo } from 'react';
import Navbar from './components/Navbar';
import AIChat from './components/AIChat';
import AdminDashboard from './components/AdminDashboard';
import MenuView from './components/MenuView';
import CartView from './components/CartView';
import AccountView from './components/AccountView';
import TraiteurView from './components/TraiteurView';
import ItemDetailsModal from './components/ItemDetailsModal';
import UpsellModal from './components/UpsellModal';
import Receipt from './components/Receipt';
import Toast, { ToastType } from './components/Toast';
import DeliveryEstimator from './components/DeliveryEstimator';
import ReviewsSection from './components/ReviewsSection';
import { Page, MenuItem, Order, Review, CartItem } from './types';
import { MENU_ITEMS, REVIEWS, LOGO_URL } from './constants';
import { playSound } from './utils/audio';
import { ShoppingBag, TrendingUp, User, Heart, Utensils, Star } from 'lucide-react';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [reviews, setReviews] = useState<Review[]>(REVIEWS);
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [isItemModalOpen, setIsItemModalOpen] = useState(false);
  const [isUpsellOpen, setIsUpsellOpen] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);
  const [toast, setToast] = useState<{ message: string, type: ToastType } | null>(null);

  // Messages de bienvenue dynamiques
  const [greetingIndex, setGreetingIndex] = useState(0);
  const greetings = [
    "SALAM 👋🏾",
    "BONJOUR 👋🏾",
    "BARKA 👋🏾",
    "FOFO 👋🏾",
    "QU'EST-CE QUE VOUS VOULEZ MANGER ? 😋"
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setGreetingIndex((prev) => (prev + 1) % greetings.length);
    }, 3500);
    return () => clearInterval(interval);
  }, []);

  const showToast = (message: string, type: ToastType = 'success') => {
    setToast({ message, type });
  };

  const handleAddToCart = (item: MenuItem, quantity: number, instructions: string) => {
    const cartItem: CartItem = { ...item, quantity, instructions };
    setCart(prev => [...prev, cartItem]);
    showToast(`${quantity}x ${item.name} ajouté !`);
    playSound('pop');

    if (item.category === 'Plat Africain' || item.category === 'Plat Européen' || item.category === 'Spécialité Maison') {
      setIsUpsellOpen(true);
    }
  };

  const handleOrderPlace = (order: Order) => {
    setOrders(prev => [order, ...prev]);
    setLastOrder(order);
    setCurrentPage(Page.HOME);
    showToast("Commande reçue ! Nos chefs s'activent. 👨‍🍳");
  };

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME:
        return (
