  const [loginPass, setLoginPass] = useState('');

  // Geste secret pour l'admin : 7 clics rapides sur l'avatar (en plus de l'email)
  const handleSecretAdmin = () => {
    const newCount = adminTapCount + 1;
    if (newCount >= 7) {
      playSound('success');
      onAdminAccess();
      setAdminTapCount(0);
    } else {
      setAdminTapCount(newCount);
      setTimeout(() => setAdminTapCount(0), 3000);
    }
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();

    // Vérification Admin
    if (loginEmail === 'admin@khadys.food' && loginPass === ADMIN_PASSWORD) {
      playSound('success');
      onLoginSuccess(true);
      return;
    }

    // Connexion Client standard
    setIsLoggedIn(true);
    playSound('success');
    onLoginSuccess(false);
