import React, { useState } from 'react';
import { CartItem, Order, PaymentMethod } from '../types';
import { Trash2, ShoppingBag, ArrowRight, MapPin, Smartphone, ChevronLeft, ShieldCheck, Wallet, CreditCard, Banknote } from 'lucide-react';
import { PhoneInput } from './PhoneInput';
import { playSound } from '../utils/audio';
import { BILLO_INFO, DISTRICTS } from '../constants';

interface CartViewProps {
  cart: CartItem[];
  setCart: React.Dispatch<React.SetStateAction<CartItem[]>>;
  onOrderPlace: (order: Order) => void;
  onClose: () => void;
}

const CartView: React.FC<CartViewProps> = ({ cart, setCart, onOrderPlace, onClose }) => {
  const [customer, setCustomer] = useState({ name: '', phone: '', address: '', district: 'Plateau' });
  const [payment, setPayment] = useState<PaymentMethod>('CASH');

  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const getDeliveryFee = () => {
    const district = DISTRICTS.find(d => d.name === customer.district);
    const hour = new Date().getHours();
    const isNight = hour >= 21 || hour < 6;

    if (!district) return 0;

    if (district.zone === 'center') {
      return isNight ? BILLO_INFO.tarifs.center.night : BILLO_INFO.tarifs.center.day;
    } else {
      return isNight ? BILLO_INFO.tarifs.periphery.night : BILLO_INFO.tarifs.periphery.day;
    }
  };

  const deliveryFee = cart.length > 0 ? getDeliveryFee() : 0;
  const total = subtotal + deliveryFee;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customer.name || !customer.phone) return alert("Complétez vos coordonnées");

    const newOrder: Order = {
      id: `KH-${Math.floor(1000 + Math.random() * 9000)}`,
      customerName: customer.name,
      phone: customer.phone,
      address: customer.address,
      district: customer.district,
      items: [...cart],
      total: subtotal,
      deliveryFee: deliveryFee,
      status: 'RECEIVED',
      paymentMethod: payment,
      timestamp: new Date().toISOString()
    };

    onOrderPlace(newOrder);
    setCart([]);
    playSound('cash');
  };

  const paymentMethods = [
    { id: 'CASH', label: 'Espèces', icon: Banknote, sub: 'À la livraison' },
    { id: 'CARD', label: 'CB / Mobile', icon: CreditCard, sub: 'Sécurisé' },
    { id: 'AIRTEL_MONEY', label: 'Airtel Money', icon: Smartphone, sub: 'Paiement direct' },
    { id: 'MOOV_MONEY', label: 'Moov / Flooz', icon: Smartphone, sub: 'Paiement direct' },
    { id: 'ZAMANY', label: 'Zamany Money', icon: Wallet, sub: 'Paiement direct' },
    { id: 'NITA', label: 'Nita', icon: Smartphone, sub: 'Transfert' },
    { id: 'MYNITA', label: 'MyNita', icon: Smartphone, sub: 'App direct' },
    { id: 'AMANA', label: 'Amana', icon: Wallet, sub: 'Transfert' },
    { id: 'AMANATA', label: 'Amanata', icon: Wallet, sub: 'Transfert' },
    { id: 'ALLIZA', label: 'Alliza', icon: Smartphone, sub: 'Transfert' },
    { id: 'ZEYNA', label: 'Zeyna', icon: Smartphone, sub: 'Transfert' },
  ];

  return (
    <div className="animate-fade-in p-6">
      <header className="mb-10 flex items-center gap-4">
        <button onClick={onClose} className="w-12 h-12 bg-white rounded-2xl shadow-sm border border-gray-100 flex items-center justify-center text-brand-brown">
           <ChevronLeft size={24} />
        </button>
        <h2 className="text-3xl font-black italic uppercase text-brand-brown leading-none">Mon <span className="text-brand-orange">Panier</span></h2>
      </header>

      {cart.length === 0 ? (
        <div className="py-20 flex flex-col items-center justify-center opacity-20 grayscale">
           <ShoppingBag size={80} className="mb-6 text-brand-brown" />
           <p className="font-black uppercase text-[10px] tracking-widest text-brand-brown mb-8 italic">Votre panier est vide</p>
           <button onClick={onClose} className="text-brand-orange font-black uppercase text-[10px] underline tracking-widest">Retour au menu</button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-8 pb-32">
          <div className="space-y-4">
             {cart.map((item, idx) => (
               <div key={idx} className="bg-white p-5 rounded-[2.5rem] flex items-center gap-5 shadow-sm border border-brand-brown/5 group transition-all hover:shadow-lg">
                  <div className="relative w-16 h-16 rounded-2xl overflow-hidden shadow-md">
                     <img src={item.image} className="w-full h-full object-cover" alt={item.name} />
                  </div>
                  <div className="flex-1">
                     <h4 className="font-black text-[10px] text-brand-brown uppercase italic truncate mb-1">{item.name}</h4>
                     <p className="text-[10px] font-black text-brand-orange bg-brand-orange/5 px-2 py-1 rounded-lg inline-block">{item.quantity} x {item.price} F</p>
                  </div>
                  <button type="button" onClick={() => { playSound('pop'); setCart(cart.filter((_, i) => i !== idx)); }} className="p-3 text-red-400 transition-transform active:scale-90"><Trash2 size={20}/></button>
               </div>
             ))}
          </div>

          <div className="bg-[#1A0F0D] p-10 rounded-[3.5rem] shadow-2xl border-4 border-white text-white relative overflow-hidden">
             <div className="absolute top-0 right-0 p-8 opacity-5 rotate-12"><MapPin size={100} /></div>
             <h3 className="text-brand-gold font-black uppercase italic text-xs tracking-widest mb-8 flex items-center gap-2 relative z-10"><MapPin size={16}/> Livraison Billo Express</h3>
             <div className="space-y-4 relative z-10">
                <input type="text" required placeholder="Votre Nom" className="w-full p-5 bg-white/5 rounded-2xl text-white text-xs font-bold outline-none border border-white/10 focus:border-brand-gold" value={customer.name} onChange={e => setCustomer({...customer, name: e.target.value})} />
                <PhoneInput value={customer.phone} onChange={(v) => setCustomer({...customer, phone: v})} required />
                <div className="relative">
                  <select className="w-full p-5 bg-white/10 rounded-2xl text-white text-xs font-bold outline-none border border-white/10 appearance-none cursor-pointer" value={customer.district} onChange={e => setCustomer({...customer, district: e.target.value})}>
                     <optgroup label="Centre-Ville (1000f)" className="bg-brand-brown">
                        {DISTRICTS.filter(d => d.zone === 'center').map(d => <option key={d.name} value={d.name}>{d.name}</option>)}
                     </optgroup>
                     <optgroup label="Périphérie (1500f)" className="bg-brand-brown">
                        {DISTRICTS.filter(d => d.zone === 'periphery').map(d => <option key={d.name} value={d.name}>{d.name}</option>)}
                     </optgroup>
                  </select>
                </div>
                <input type="text" placeholder="Précisions adresse (Villa n°, Rue...)" className="w-full p-5 bg-white/5 rounded-2xl text-white text-xs font-bold outline-none border border-white/10 focus:border-brand-gold" value={customer.address} onChange={e => setCustomer({...customer, address: e.target.value})} />
             </div>
          </div>

          <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-gray-100">
             <h3 className="text-brand-brown font-black uppercase italic text-xs tracking-widest mb-8 flex items-center gap-3"><Smartphone size={16} className="text-brand-orange"/> Mode de Paiement</h3>
             <div className="grid grid-cols-1 gap-3">
                {paymentMethods.map(m => (
                  <button key={m.id} type="button" onClick={() => { playSound('pop'); setPayment(m.id as any); }} className={`p-4 rounded-3xl flex items-center gap-4 text-[9px] font-black uppercase border-4 transition-all shadow-sm ${payment === m.id ? 'border-brand-orange bg-brand-orange text-white shadow-brand-orange/20' : 'border-gray-50 bg-gray-50 text-brand-brown/40'}`}>
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${payment === m.id ? 'bg-white text-brand-orange' : 'bg-white/50 text-brand-brown/20'}`}>
                      <m.icon size={18} />
                    </div>
                    <div className="text-left">
                      <p className="font-black">{m.label}</p>
                      <p className={`text-[7px] font-bold opacity-50 ${payment === m.id ? 'text-white' : 'text-brand-brown'}`}>{m.sub}</p>
                    </div>
                  </button>
                ))}
             </div>
          </div>

          <div className="bg-brand-brown p-10 rounded-[4rem] text-brand-gold shadow-2xl relative overflow-hidden border-4 border-white">
             <div className="space-y-4 mb-8">
                <div className="flex justify-between text-white/40 text-[9px] font-black uppercase tracking-widest"><span>Sous-total Festin</span><span>{subtotal} F</span></div>
                <div className="flex justify-between text-brand-gold text-[9px] font-black uppercase tracking-widest"><span>Service Billo (Zone {DISTRICTS.find(d => d.name === customer.district)?.zone})</span><span>{deliveryFee} F</span></div>
                <div className="pt-6 border-t border-white/10 flex justify-between items-end"><span className="text-white font-black italic uppercase text-sm">Net à Payer</span><span className="text-4xl font-black">{total} F</span></div>
             </div>
             <button type="submit" className="w-full bg-brand-orange text-white py-6 rounded-[2.5rem] font-black uppercase shadow-[0_20px_50px_rgba(255,111,0,0.3)] flex items-center justify-center gap-4 active:scale-95 transition-all italic tracking-widest">Confirmer le Festin <ArrowRight size={22}/></button>
             <p className="text-center text-[8px] text-white/20 font-black uppercase tracking-widest mt-6">Sécurisé par Khady's Payment Terminal</p>
          </div>
        </form>
      )}
    </div>
  );
};

export default CartView;

import React, { useState, useEffect, useRef } from 'react';
import { Home, ScrollText, ShoppingBag, Sparkles, UserRound } from 'lucide-react';
import { Page } from '../types';
import { playSound } from '../utils/audio';

interface NavbarProps {
  currentPage: Page;
  setPage: (page: Page) => void;
  cartCount: number;
}

const Navbar: React.FC<NavbarProps> = ({ currentPage, setPage, cartCount }) => {
  const [isBouncing, setIsBouncing] = useState(false);
  const prevCount = useRef(cartCount);

  useEffect(() => {
    if (cartCount > prevCount.current) {
      setIsBouncing(true);
      const timer = setTimeout(() => setIsBouncing(false), 600);
      return () => clearTimeout(timer);
    }
    prevCount.current = cartCount;
  }, [cartCount]);

  const navItems = [
    { page: Page.HOME, icon: Home, label: 'Accueil' },
    { page: Page.MENU, icon: ScrollText, label: 'Menu' },
    { page: Page.TRAITEUR, icon: Sparkles, label: 'Event' },
    { page: Page.CART, icon: ShoppingBag, label: 'Panier', badge: cartCount },
    { page: Page.COMPTE, icon: UserRound, label: 'Moi' },
  ];

  return (
    <div className="fixed bottom-8 left-0 right-0 z-50 px-6 flex justify-center">
      <nav className="bg-white/80 backdrop-blur-2xl border border-gray-100 shadow-[0_20px_50px_rgba(0,0,0,0.1)] flex justify-between items-center h-20 px-4 rounded-[2.5rem] w-full max-w-sm">
          {navItems.map((item) => {
            const isActive = currentPage === item.page;
            const isCart = item.page === Page.CART;
            const Icon = item.icon;

            return (
              <button 
                key={item.label} 
                onClick={() => { playSound('pop'); setPage(item.page); }} 
                className="relative flex flex-col items-center justify-center flex-1 h-full group"
              >
                <div className={`relative p-3 rounded-2xl transition-all duration-300 ${isActive ? 'bg-brand-brown text-brand-gold shadow-lg shadow-brand-brown/20 scale-110' : 'text-gray-300 group-hover:text-brand-brown'} ${isCart && isBouncing ? 'animate-bounce-subtle' : ''}`}>
                  <Icon size={20} strokeWidth={isActive ? 2 : 1.2} />

                  {item.badge ? (
                    <span className={`absolute -top-1 -right-1 bg-brand-orange text-white text-[8px] font-black w-4 h-4 rounded-full flex items-center justify-center border-2 border-white shadow-md transition-transform ${isBouncing && isCart ? 'scale-150' : 'scale-100'}`}>
                      {item.badge}
                    </span>
                  ) : null}
                </div>
              </button>
            );
          })}
      </nav>
    </div>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { Order, OrderStatus } from '../types';
import { playSound } from '../utils/audio';
import { Clock, CheckCircle2, ChefHat, Bike, PackageCheck, Box, Bell, MapPin, Navigation, Zap, MessageSquare } from 'lucide-react';

interface OrderTrackingProps {
  order: Order;
  onComplete: () => void;
}

const steps: { status: OrderStatus; label: string; icon: any; sound: any }[] = [
  { status: 'RECEIVED', label: 'Reçue', icon: Box, sound: 'pop' },
  { status: 'CONFIRMED', label: 'Confirmée', icon: CheckCircle2, sound: 'notification' },
  { status: 'PREPARING', label: 'En Cuisine', icon: ChefHat, sound: 'notification' },
  { status: 'READY', label: 'Emballée !', icon: PackageCheck, sound: 'success' },
  { status: 'DELIVERING', label: 'En Livraison', icon: Bike, sound: 'delivery' },
  { status: 'DELIVERED', label: 'Livrée 🍽️', icon: Zap, sound: 'success' }
];

const OrderTracking: React.FC<OrderTrackingProps> = ({ order, onComplete }) => {
  const [currentStepIdx, setCurrentStepIdx] = useState(0);
  const [billoPos, setBilloPos] = useState(0);

  useEffect(() => {
    const actualIdx = steps.findIndex(s => s.status === order.status);
    if (actualIdx !== -1) {
      setCurrentStepIdx(actualIdx);
      if (order.status === 'DELIVERED') onComplete();
    }
  }, [order.status]);

  useEffect(() => {
    if (steps[currentStepIdx].status === 'DELIVERING') {
      const interval = setInterval(() => {
        setBilloPos(prev => (prev < 100 ? prev + 1 : 100));
      }, 300);
      return () => clearInterval(interval);
    }
  }, [currentStepIdx]);

  const isDelivered = order.status === 'DELIVERED';

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="bg-white p-10 rounded-[4rem] shadow-2xl border border-brand-brown/5 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-40 h-40 bg-brand-orange/5 rounded-full -mr-20 -mt-20"></div>

        <div className="flex justify-between items-center mb-10 relative z-10">
           <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.4em] mb-1 italic">Statut Khady's</p>
              <h3 className="text-2xl font-black italic text-brand-brown uppercase tracking-tighter">{order.id}</h3>
           </div>
           <div className="w-14 h-14 bg-brand-brown rounded-[1.8rem] flex items-center justify-center text-brand-gold shadow-xl border-4 border-white animate-pulse">
              {isDelivered ? <CheckCircle2 size={28} /> : <Navigation size={28} />}
           </div>
        </div>

        <div className="space-y-8 relative z-10">
           {steps.map((step, idx) => {
              const isCompleted = idx < currentStepIdx;
              const isCurrent = idx === currentStepIdx;
              const Icon = step.icon;

              return (
                 <div key={idx} className={`flex items-center gap-6 transition-all duration-1000 ${isCurrent ? 'scale-110 opacity-100' : isCompleted ? 'opacity-40' : 'opacity-10'}`}>
                    <div className="relative">
                       {idx < steps.length - 1 && (
                         <div className={`absolute left-1/2 -translate-x-1/2 top-full w-0.5 h-8 ${isCompleted ? 'bg-brand-orange' : 'bg-gray-100'}`}></div>
                       )}
                       <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border-4 transition-all duration-500 ${isCurrent || isCompleted ? 'bg-brand-orange text-white border-white shadow-2xl' : 'bg-gray-50 text-gray-300 border-gray-100'}`}>
                          <Icon size={24} className={isCurrent ? 'animate-bounce' : ''} />
                       </div>
                    </div>
                    <div>
                       <p className="text-[8px] font-black uppercase tracking-[0.3em] text-gray-400 mb-0.5">Étape {idx + 1}</p>
                       <p className={`text-base font-black italic uppercase tracking-tighter ${isCurrent ? 'text-brand-brown' : 'text-gray-400'}`}>{step.label}</p>
                    </div>
                 </div>
              );
           })}
        </div>
      </div>

      {isDelivered && (
        <div className="bg-green-500 p-8 rounded-[3rem] text-white shadow-2xl animate-slide-up border-4 border-white">
          <div className="flex items-center gap-4 mb-4">
            <div className="bg-white/20 p-3 rounded-2xl">
              <MessageSquare size={20} />
            </div>
            <h4 className="font-black uppercase italic text-xs">Message du Livreurs Billo</h4>
          </div>
          <p className="text-sm font-bold italic leading-relaxed">
            "Votre festin Khady's a été livré ! Bon appétit et merci de votre confiance. Barka !"
          </p>
        </div>
      )}

      {(steps[currentStepIdx].status === 'DELIVERING' || steps[currentStepIdx].status === 'READY') && (
