                      <div className="w-full h-36 overflow-hidden rounded-[1.8rem] mb-4 shadow-md">
                        <img src={item.image} className="w-full h-full object-cover transition-transform duration-700 hover:scale-110" alt={item.name} />
                      </div>
                      <h4 className="text-[9px] font-black uppercase text-brand-brown italic mb-2 truncate">{item.name}</h4>
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black text-brand-orange">{item.price} F</span>
                        <div className="flex gap-0.5">
                          {[...Array(4)].map((_, i) => <Star key={i} size={8} fill="#FFD700" className="text-brand-gold" />)}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </section>

            <div className="px-6 mb-10">
              <DeliveryEstimator />
            </div>

            <div className="px-6">
              <ReviewsSection reviews={reviews} />
            </div>
          </div>
        );
      case Page.MENU:
        return <MenuView items={items} onSelectItem={(item) => { setSelectedItem(item); setIsItemModalOpen(true); }} />;
      case Page.TRAITEUR:
        return <TraiteurView />;
      case Page.CART:
        return <CartView cart={cart} setCart={setCart} onOrderPlace={handleOrderPlace} onClose={() => setCurrentPage(Page.MENU)} />;
      case Page.COMPTE:
        return <AccountView orders={orders} onAdminAccess={() => setCurrentPage(Page.ADMIN)} onLoginSuccess={(isAdmin) => isAdmin ? setCurrentPage(Page.ADMIN) : setCurrentPage(Page.COMPTE)} />;
      case Page.ADMIN:
        return <AdminDashboard items={items} setItems={setItems} orders={orders} setOrders={setOrders} reviews={reviews} setReviews={setReviews} onExit={() => setCurrentPage(Page.COMPTE)} />;
      default:
        return <MenuView items={items} onSelectItem={(item) => { setSelectedItem(item); setIsItemModalOpen(true); }} />;
    }
  };

  const upsellSuggestions = useMemo(() => {
    return items.filter(i => i.category === 'Boisson Froide' || i.category === 'Dessert').slice(0, 3);
  }, [items]);

  return (
    <div className="min-h-screen bg-[#FDFCFB] font-sans text-brand-brown selection:bg-brand-orange selection:text-white">
      {renderPage()}

      {currentPage !== Page.ADMIN && (
        <>
          <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.reduce((a, b) => a + b.quantity, 0)} />
          <AIChat />
        </>
      )}

      <ItemDetailsModal 
        item={selectedItem} 
        isOpen={isItemModalOpen} 
        onClose={() => setIsItemModalOpen(false)} 
        onAddToCart={handleAddToCart} 
      />

      <UpsellModal 
        isOpen={isUpsellOpen} 
        onClose={() => setIsUpsellOpen(false)} 
        suggestions={upsellSuggestions}
        onAdd={(item) => { handleAddToCart(item, 1, ''); setIsUpsellOpen(false); }}
        onProceed={() => { setIsUpsellOpen(false); setCurrentPage(Page.CART); }}
      />

      {lastOrder && (
        <Receipt order={lastOrder} onClose={() => setLastOrder(null)} />
      )}

      {toast && (
        <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { 
  LayoutDashboard, ShoppingBag, Utensils, X, TrendingUp, Star, 
  Settings, Bike, Sparkles, Zap, Plus, Trash2, 
  Edit3, Power, RefreshCw, Users, Package, 
  Calendar, Smartphone, CheckCircle2, ChefHat, PackageCheck, Bell, Camera, 
  MapPin, Clock, Heart, Sliders, DollarSign, MessageCircle, AlertCircle,
  UserRound, Save, ToggleLeft as Toggle, Image as ImageIcon
} from 'lucide-react';
import { MenuItem, AdminView, Order, Review, MenuCategory, OrderStatus } from '../types';
import { KhadyLogo } from './KhadyLogo';
import { playSound } from '../utils/audio';
import { GoogleGenAI } from "@google/genai";
import { DISTRICTS, BILLO_INFO } from '../constants';

interface AdminDashboardProps {
  items: MenuItem[];
  setItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  orders: Order[];
  setOrders: React.Dispatch<React.SetStateAction<Order[]>>;
  reviews: Review[];
  setReviews: React.Dispatch<React.SetStateAction<Review[]>>;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  items, setItems, onExit, setOrders, orders, reviews, setReviews 
}) => {
  const [currentView, setCurrentView] = useState<AdminView>(AdminView.DASHBOARD);
  const [editingItem, setEditingItem] = useState<Partial<MenuItem> | null>(null);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [aiStrategy, setAiStrategy] = useState('');
  const [isRestaurantOpen, setIsRestaurantOpen] = useState(true);
  const adminPhotoInputRef = useRef<HTMLInputElement>(null);
  const [adminAvatar, setAdminAvatar] = useState(() => localStorage.getItem('khadys_admin_avatar') || '');

  const handleAdminPhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setAdminAvatar(base64String);
        localStorage.setItem('khadys_admin_avatar', base64String);
        playSound('success');
      };
      reader.readAsDataURL(file);
    }
  };

