import { createClient } from '@supabase/supabase-js';
import { MenuItem, Order } from '../types';

const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

export const isSupabaseConfigured = 
  supabaseUrl.startsWith('https://') && 
  supabaseKey.length > 20;

export const supabase = isSupabaseConfigured 
  ? createClient(supabaseUrl, supabaseKey) 
  : null;

/**
 * SERVICE DE DONNÉES KHADY'S ELITE
 * Gère la synchronisation entre l'App et le Cloud
 */
export const db = {
  // --- MENU ---
  fetchMenu: async (): Promise<MenuItem[] | null> => {
    if (!supabase) return null;
    const { data, error } = await supabase
      .from('menu_items')
      .select('*')
      .order('category', { ascending: true });
    if (error) throw error;
    return data as MenuItem[];
  },

  saveMenuItem: async (item: MenuItem) => {
    if (!supabase) return null;
    const { data, error } = await supabase
      .from('menu_items')
      .upsert({
        id: item.id,
        name: item.name,
        description: item.description,
        price: item.price,
        image: item.image,
        category: item.category,
        rating: item.rating,
        is_available: item.isAvailable,
        is_spicy: item.isSpicy,
        is_specialite_maison: item.isSpécialitéMaison
      })
      .select();
    if (error) throw error;
    return data;
  },

  deleteMenuItem: async (id: string) => {
    if (!supabase) return null;
    const { error } = await supabase.from('menu_items').delete().eq('id', id);
    if (error) throw error;
  },

  // --- COMMANDES ---
  fetchOrders: async (): Promise<Order[] | null> => {
    if (!supabase) return null;
    const { data, error } = await supabase
      .from('orders')
      .select('*')
      .order('timestamp', { ascending: false });
    if (error) throw error;
    return data as unknown as Order[];
  },

  placeOrder: async (order: Order) => {
    if (!supabase) return null;
    const { data, error } = await supabase
      .from('orders')
      .insert({
        id: order.id,
        customer_name: order.customerName,
        phone: order.phone,
        items: order.items,
        total: order.total,
        delivery_fee: order.deliveryFee,
        status: order.status,
        payment_method: order.paymentMethod,
        timestamp: order.timestamp,
        district: order.district,
        address: order.address
      })
      .select();
    if (error) throw error;
    return data;
  },

  updateOrderStatus: async (orderId: string, status: string) => {
    if (!supabase) return null;
    const { error } = await supabase
      .from('orders')
      .update({ status })
      .eq('id', orderId);
    if (error) throw error;
  }
};

